import json
from pathlib import Path
from unittest.mock import patch
import scripts.validate_chinese_memory as v
reports={str(s):json.loads((v.ROOT/f'runs/p26-query-b/seed{s}/report.json').read_text('utf-8')) for s in (7,11,23)}
for r in reports.values():
    r['checkpoint_sha256']='0'*64
    r['source_sha256']={k:'0'*64 for k in r['source_sha256']}
def fake_read(path,*a,**kw): return json.dumps(reports[path.parent.name.removeprefix('seed')])
class ReachedFinal(Exception): pass
with patch.object(Path,'mkdir'), patch.object(Path,'write_text') as writes, patch.object(Path,'read_text',fake_read), patch.object(v,'module_at',side_effect=ReachedFinal):
    try: v.main()
    except ReachedFinal: print('reached_final', True, 'mocked_writes', writes.call_count)
